`timescale 1ns/1ps
// Behavioural stand-in for the vio_cfg IP (generated by fpga/build.tcl) so
// fpga_top simulates without Vivado. The outputs start at the same values as
// the IP's INIT values; a testbench changes them hierarchically, e.g.
//   dut.u_vio.probe_out0 = 32'h...;  dut.u_vio.probe_out4 = 1'b1;
// Never add this file to a Vivado build.
module vio_cfg (
    input clk,
    input [31:0] probe_in0,
    input [15:0] probe_in1,
    input [15:0] probe_in2,
    input [15:0] probe_in3,
    output reg [31:0]  probe_out0 = 32'h0021_0204,
    output reg [31:0]  probe_out1 = 32'h0000_0001,
    output reg [127:0] probe_out2 = 128'h03FE0100_0002FD05_020100FF_04030201,
    output reg [127:0] probe_out3 = 128'h02FF0101_0100FE03_00010100_FF020001,
    output reg [0:0]   probe_out4 = 1'b0
);
endmodule
